import React from 'react'
import { useNavigate } from 'react-router-dom'
import NavBar from '../Components/NavBar'
import Footer from '../Components/Footer'
import './advertisements.css'

const posters = [
  {
    id: 1,
    title: 'Modern Apartment for Rent',
    imageUrl: '/Images/home1.jpeg',
    description: 'A beautiful, fully-furnished modern apartment in the city center. Perfect for young professionals.',
    price: '$1200/month'
  },
  {
    id: 2,
    title: 'Spacious Family House for Sale',
    imageUrl: '/Images/home2.jpeg',
    description: 'A spacious three-bedroom house with a large backyard. Located in a quiet, family-friendly neighborhood.',
    price: '$350,000'
  }
  // Added more details to make the cards richer
]

export default function Advertisements() {
  const navigate = useNavigate()

  const goToDetail = (poster) => {
    // Pass poster data via state
    navigate(`/advertisement/${poster.id}`, { state: poster })
  }

  return (
    <div className="advertisements-page">
      <NavBar />
      
      <main className="content-area">
        <header className="page-header">
          <h1>Featured Advertisements</h1>
          <p>Browse our latest listings and find your next dream property!</p>
        </header>

        <section className="posters-grid"> {/* Changed container name for clarity */}
          {posters.map((poster) => (
            <article // Use <article> for semantic clarity
              key={poster.id}
              className="poster-card"
              onClick={() => goToDetail(poster)}
            >
              <div className="poster-image-wrapper">
                <img src={poster.imageUrl} alt={poster.title} className="poster-image" />
              </div>
              <div className="poster-info">
                <h3 className="poster-title">{poster.title}</h3>
                <p className="poster-description">{poster.description}</p>
                <button className="view-details-btn">View Details</button>
              </div>
            </article>
          ))}
        </section>
      </main>

      <Footer />
    </div>
  )
}
